using UnityEngine;
using UnityEditor;
using System;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x / 1.25f, (y + 55) / 1.25f);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            click(700, 266);
            click(600, 400);
            foreach (char c in "Chua du can cu ve thoi diem.")
                w.SendEvent(new Event{type = EventType.KeyDown, character = c});
            click(435, 830);
            w.SendEvent(new Event{type = EventType.ScrollWheel, mousePosition = new Vector2(1400, 650), delta = new Vector2(0, 30)});
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/conclusion-ui-confirm.png");
            r.Log("Synthetic UI selects insufficient, types claim, toggles consent; no API writes to conclusion data");
        }
    }
}

